// @FIGURE_CODE_BEGIN
var amesDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var VBW = 660, VBH = 880;
amesDraw.viewbox(0, 0, VBW, VBH);
var amesRoot = amesDraw.group();

var WL = 40, WR = 630, WB = 800, WT = 30, OBJR = 52;
var SERIF = "'Times New Roman',Times,serif";
var RED = '#ff0000', GRAY = '#bebebe';

var st = { skew: 25, px: 430, overlay: 'Both', rays: 'back', hint: false };

/* ---------- geometry helpers ---------- */
function geo() {
  var m = Math.tan(st.skew * Math.PI / 180) * 1.15;
  var yR = WT + (WR - WL) * m;
  var wy = function (x) { return WT + (x - WL) * m; };
  var cL = { x: WL + 62 }; cL.y = wy(cL.x) + OBJR + 10;
  var cR = { x: WR - 68 }; cR.y = wy(cR.x) + OBJR + 36;
  var P = { x: st.px, y: WB };
  var poly = [{ x: WL, y: WT }, { x: WR, y: yR }, { x: WR, y: WB }, { x: WL, y: WB }];
  return { m: m, yR: yR, wy: wy, cL: cL, cR: cR, P: P, poly: poly };
}

function dist(a, b) { return Math.hypot(a.x - b.x, a.y - b.y); }

/* back-project a point onto the perceived (assumed rectangular) floor depth */
function backProj(Q, g) {
  var P = g.P, dx = Q.x - P.x, dy = Q.y - P.y;
  var den = dy - g.m * dx;
  var tA = (WT + (P.x - WL) * g.m - P.y) / den;
  var tP = (g.yR - P.y) / dy;
  var k = (Math.abs(tA) < 1e-9) ? 1 : tP / tA;
  return { x: P.x + k * dx, y: P.y + k * dy, k: k };
}

function raySeg(P, d, A, Bp) {
  var ex = Bp.x - A.x, ey = Bp.y - A.y;
  var den = d.x * ey - d.y * ex;
  if (Math.abs(den) < 1e-9) return null;
  var t = ((A.x - P.x) * ey - (A.y - P.y) * ex) / den;
  var u = ((A.x - P.x) * d.y - (A.y - P.y) * d.x) / den;
  if (t > 1e-6 && u >= -1e-6 && u <= 1 + 1e-6) return t;
  return null;
}

function exitPt(P, d, poly) {
  var best = null;
  for (var i = 0; i < poly.length; i++) {
    var A = poly[i], Bp = poly[(i + 1) % poly.length];
    var t = raySeg(P, d, A, Bp);
    if (t !== null && (best === null || t < best)) best = t;
  }
  if (best === null) best = 600;
  return { x: P.x + best * d.x, y: P.y + best * d.y };
}

function tangentAngles(P, C, r) {
  var dx = C.x - P.x, dy = C.y - P.y, d = Math.hypot(dx, dy);
  if (d <= r * 1.02) return null;
  var base = Math.atan2(dy, dx), a = Math.asin(r / d);
  return [base - a, base + a];
}

function visAngle(P, C, r) {
  var d = dist(P, C);
  return 2 * Math.asin(Math.min(0.999, r / d)) * 180 / Math.PI;
}

/* ---------- drawing helpers ---------- */
function mkLabel(grp, str, size) {
  var t = grp.text(str);
  t.font({ family: SERIF, size: size, anchor: 'middle', leading: 1 });
  t.fill('#000');
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  return t;
}

function hoverable(el, text, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(text, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, body); });
  return el;
}

function drawWedge(rayG, wedgeG, P, C, r, poly, op, wid) {
  var ang = tangentAngles(P, C, r);
  if (!ang) return null;
  var pts = [];
  for (var i = 0; i < 2; i++) {
    var d = { x: Math.cos(ang[i]), y: Math.sin(ang[i]) };
    var ex = exitPt(P, d, poly);
    ex = { x: ex.x + d.x * 12, y: ex.y + d.y * 12 };
    pts.push(ex);
    var ln = rayG.line(P.x, P.y, ex.x, ex.y)
      .stroke({ color: RED, width: wid, linecap: 'round', opacity: op });
    hoverable(ln, 'Sight line: a ray through the pinhole grazing the object',
      'Sight line',
      'A pinhole passes only rays that pass through one point, so the image records the direction of each ray — the visual angle — but nothing about how far along the ray the object actually sits.');
  }
  wedgeG.polygon([[P.x, P.y], [pts[0].x, pts[0].y], [pts[1].x, pts[1].y]])
    .fill({ color: RED, opacity: 0.06 }).stroke('none');
  return pts;
}

/* ---------- main render ---------- */
function amesRender() {
  amesRoot.clear();
  var g = geo();
  var showA = st.overlay !== 'Perceived';
  var showP = st.overlay !== 'Actual';

  var gW = amesRoot.group(), gRoom = amesRoot.group(), gRay = amesRoot.group(),
    gObj = amesRoot.group(), gLab = amesRoot.group(), gUI = amesRoot.group();

  var pc = backProj(g.cL, g);
  var pcorner = backProj({ x: WL, y: WT }, g);
  var xPL = Math.max(WL, Math.min(WR - 60, pcorner.x));

  /* ---- actual room ---- */
  if (showA) {
    var pts = g.poly.map(function (p) { return [p.x, p.y]; });
    gRoom.polygon(pts).fill('none').stroke({ color: '#000', width: 4.5, linejoin: 'miter' });
    var wall = gRoom.line(WL, WT, WR, g.yR).stroke({ color: '#000', width: 4.5, opacity: 0.001 });
    hoverable(wall, 'Actual far wall — slant ' + st.skew + '°', 'Actual far wall',
      'The real far wall recedes steeply on the left. Because the pinhole cannot measure depth, this slanted wall projects to exactly the same image as a wall square to the viewer.');
  }

  /* ---- perceived room ---- */
  if (showP) {
    gRoom.line(xPL, g.yR, WR, g.yR)
      .stroke({ color: '#000', width: 4, dasharray: '22,16', linecap: 'butt' });
    gRoom.line(xPL, g.yR, xPL, WB)
      .stroke({ color: '#000', width: 4, dasharray: '22,16', linecap: 'butt' });
    var hitH = gRoom.line(xPL, g.yR, WR, g.yR).stroke({ color: '#000', width: 16, opacity: 0.001 });
    hoverable(hitH, 'Perceived (assumed rectangular) floor plan', 'Perceived room',
      'This dashed rectangle is the room the brain assumes: right angles everywhere. It projects to the same retinal image as the real trapezoid, so nothing in the image can rule it out.');
  }

  /* ---- sight lines ---- */
  if (st.rays !== 'none') {
    drawWedge(gRay, gW, g.P, g.cL, OBJR, g.poly, 1, 5.5);
    if (st.rays === 'both') drawWedge(gRay, gW, g.P, g.cR, OBJR, g.poly, 1, 5.5);
    var dC = { x: g.cL.x - g.P.x, y: g.cL.y - g.P.y };
    var n = Math.hypot(dC.x, dC.y); dC.x /= n; dC.y /= n;
    var exC = exitPt(g.P, dC, g.poly);
    gRay.line(g.P.x, g.P.y, exC.x, exC.y).stroke({ color: '#000', width: 1.6 });
  }

  /* ---- objects ---- */
  if (showA) {
    var c1 = gObj.circle(OBJR * 2).center(g.cL.x, g.cL.y)
      .fill(GRAY).stroke({ color: '#000', width: 4.5 });
    hoverable(c1, 'Actual object, far corner — subtends ' + visAngle(g.P, g.cL, OBJR).toFixed(1) + '° at the pinhole',
      'Far object (actual)',
      'This object really sits in the deep far-left corner of the trapezoid. Its distance from the pinhole is large, so it fills only a narrow cone of directions.');
    var c2 = gObj.circle(OBJR * 2).center(g.cR.x, g.cR.y)
      .fill(GRAY).stroke({ color: '#000', width: 4.5 });
    hoverable(c2, 'Actual object, near corner — subtends ' + visAngle(g.P, g.cR, OBJR).toFixed(1) + '° at the pinhole',
      'Near object (actual)',
      'Physically identical to the far object, but much closer to the pinhole. In the real Ames room the two corners differ so much in depth that two equal people look wildly unequal.');
  }

  if (showP && st.rays === 'back') {
    var pr = Math.max(4, OBJR * pc.k);
    var c3 = gObj.circle(pr * 2).center(pc.x, pc.y)
      .fill(GRAY).stroke({ color: '#000', width: 3.5, dasharray: '10,8' });
    hoverable(c3, 'Perceived object — ' + (pc.k * 100).toFixed(0) + '% of the true size',
      'Perceived object',
      'Back-projecting the same sight lines onto the assumed rectangular floor puts the object much nearer than it really is. Same visual angle at a nearer assumed depth can only mean a smaller object — so the brain shrinks it.');
  }

  /* ---- labels ---- */
  if (showA) {
    var mx = WL + 0.55 * (WR - WL), my = g.wy(mx);
    var nn = Math.hypot(1, g.m);
    var lx = mx + 24 * g.m / nn, ly = my - 24 / nn;
    var tA = mkLabel(gLab, 'Actual room floor plan', 30);
    tA.center(lx, ly);
    tA.rotate(Math.atan2(g.m, 1) * 180 / Math.PI);
  }
  if (showP) {
    var tP = mkLabel(gLab, 'Perceived room floor plan', 28);
    tP.center((xPL + WR) / 2, g.yR - 20);
  }
  if (showP && st.rays === 'back') {
    var prr = Math.max(4, OBJR * pc.k);
    var leftX = pc.x - prr - 14;
    var l1 = mkLabel(gLab, 'Perceived', 30);
    var l2 = mkLabel(gLab, 'object', 30);
    var b1 = l1.bbox(), b2 = l2.bbox();
    if (leftX - b1.width > WL + 8) {
      l1.center(leftX - b1.width / 2, pc.y - 18);
      l2.center(leftX - b2.width / 2, pc.y + 18);
    } else {
      var rx = pc.x + prr + 14;
      l1.center(rx + b1.width / 2, pc.y - 18);
      l2.center(rx + b2.width / 2, pc.y + 18);
    }
  }

  /* ---- pinhole ---- */
  var ph = gUI.circle(16).center(g.P.x, g.P.y).fill('#000');
  var hit = gUI.circle(46).center(g.P.x, g.P.y).fill('#ffffff').attr('fill-opacity', 0.001);
  var tPh = mkLabel(gLab, 'Pinhole', 30);
  tPh.center(g.P.x, WB + 38);

  if (st.hint) {
    var ring = gUI.circle(44).center(g.P.x, g.P.y).fill('none').stroke({ color: RED, width: 3 });
    try { ring.animate(900).attr({ 'stroke-opacity': 0.05 }).loop(true, true); } catch (e) { }
  }

  hoverable(hit, 'Drag me along the bottom wall', 'Pinhole',
    'All the light reaching the eye passes through this single point, so only ray directions survive. Move it and the whole construction changes: the illusion is built for exactly one viewpoint.');
  hit.css('cursor', 'ew-resize');
  hit.on('pointerdown', function (e) { amesDragging = true; e.preventDefault(); });
  ph.css('cursor', 'ew-resize');
  ph.on('pointerdown', function (e) { amesDragging = true; e.preventDefault(); });
}

/* ---------- drag ---------- */
var amesDragging = false;
document.addEventListener('pointermove', function (e) {
  if (!amesDragging) return;
  var p = amesDraw.point(e.clientX, e.clientY);
  var x = Math.max(230, Math.min(600, p.x));
  st.px = x;
  var inp = document.getElementById('pinholeDragInput');
  if (inp) inp.value = Math.round(x);
  var out = document.getElementById('pinholeDragVal');
  if (out) out.value = Math.round(x);
  amesRender(); updReadout();
});
document.addEventListener('pointerup', function () { amesDragging = false; });

/* ---------- readout ---------- */
function updReadout() {
  var el = document.getElementById('amesReadout');
  if (!el) return;
  var g = geo();
  var aL = visAngle(g.P, g.cL, OBJR), aR = visAngle(g.P, g.cR, OBJR);
  var k = backProj(g.cL, g).k;
  el.innerHTML =
    'Visual angle — far object <b>' + aL.toFixed(1) + '°</b>, near object <b>' + aR.toFixed(1) + '°</b><br>' +
    'Assumed depth ÷ true depth = <b>' + k.toFixed(2) + '</b><br>' +
    'Far object is perceived at <b>' + (k * 100).toFixed(0) + '%</b> of its real size' +
    (k > 0.995 ? ' (no illusion)' : '');
}

/* ---------- interaction handlers ---------- */
function update_skewAngle(v) { st.skew = v; amesRender(); updReadout(); }
function update_pinholeDrag(v) { st.px = v; amesRender(); updReadout(); }
function toggle_planOverlay(v) { st.overlay = v; amesRender(); updReadout(); }
function toggle_rayReveal(v) { st.rays = v; amesRender(); updReadout(); }

