// @FIGURE_CODE_BEGIN
var amesDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var VBW = 660, VBH = 888;
amesDraw.viewbox(0, 0, VBW, VBH);
var amesRoot = amesDraw.group();

/* room box proportions taken from the source plate */
var WL = 14, WR = 650, WT = 12, WB = 843, OBJR = 58;
var SERIF = "'Times New Roman',Times,serif";
var RED = '#ff0000', GRAY = '#bebebe';

var st = { skew: 25, px: 424, overlay: 'Both', rays: 'back', wedge: false, hint: false };

/* ---------- geometry ---------- */
function geo() {
  var m = Math.tan(st.skew * Math.PI / 180) * 1.217;   /* 25° -> slope 0.568, matching the plate */
  var nn = Math.sqrt(1 + m * m);
  var yR = WT + (WR - WL) * m;
  var wy = function (x) { return WT + (x - WL) * m; };
  /* far object: tucked into the far-left corner, visibly crossing BOTH the
     slanted far wall and the left wall exactly as in the printed plate */
  var cLx = WL + 0.72 * OBJR;
  var cL = { x: cLx, y: wy(cLx) + 0.80 * OBJR * nn };
  /* near object: just inside the far wall at the right, close to the pinhole */
  var cR = { x: WR - 0.98 * OBJR, y: Math.min(WB - OBJR - 16, yR + 1.14 * OBJR) };
  var P = { x: st.px, y: WB };
  var poly = [{ x: WL, y: WT }, { x: WR, y: yR }, { x: WR, y: WB }, { x: WL, y: WB }];
  return { m: m, nn: nn, yR: yR, wy: wy, cL: cL, cR: cR, P: P, poly: poly };
}
function dist(a, b) { return Math.hypot(a.x - b.x, a.y - b.y); }

/* back-project a point along its sight line onto the assumed (rectangular) floor depth */
function backProj(Q, g) {
  var P = g.P, dx = Q.x - P.x, dy = Q.y - P.y;
  var den = dy - g.m * dx;
  if (Math.abs(den) < 1e-9 || Math.abs(dy) < 1e-9) return { x: Q.x, y: Q.y, k: 1 };
  var tA = (WT + (P.x - WL) * g.m - P.y) / den;   /* ray parameter at the actual far wall */
  var tP = (g.yR - P.y) / dy;                     /* ray parameter at the assumed far wall */
  var k = (Math.abs(tA) < 1e-9) ? 1 : tP / tA;
  return { x: P.x + k * dx, y: P.y + k * dy, k: k };
}
function raySeg(P, d, A, Bp) {
  var ex = Bp.x - A.x, ey = Bp.y - A.y;
  var den = d.x * ey - d.y * ex;
  if (Math.abs(den) < 1e-9) return null;
  var t = ((A.x - P.x) * ey - (A.y - P.y) * ex) / den;
  var u = ((A.x - P.x) * d.y - (A.y - P.y) * d.x) / den;
  if (t > 1e-6 && u >= -1e-6 && u <= 1 + 1e-6) return t;
  return null;
}
function exitPt(P, d, poly) {
  var best = null;
  for (var i = 0; i < poly.length; i++) {
    var t = raySeg(P, d, poly[i], poly[(i + 1) % poly.length]);
    if (t !== null && (best === null || t < best)) best = t;
  }
  if (best === null) best = 900;
  return { x: P.x + best * d.x, y: P.y + best * d.y };
}
/* run a ray all the way to the edge of the plate, like the printed figure */
function exitBox(P, d) {
  var ts = [];
  if (d.x > 1e-9) ts.push((VBW - P.x) / d.x); else if (d.x < -1e-9) ts.push((0 - P.x) / d.x);
  if (d.y > 1e-9) ts.push((VBH - P.y) / d.y); else if (d.y < -1e-9) ts.push((0 - P.y) / d.y);
  var t = 1e9;
  for (var i = 0; i < ts.length; i++) if (ts[i] > 0 && ts[i] < t) t = ts[i];
  if (t > 1e8) t = 900;
  return { x: P.x + t * d.x, y: P.y + t * d.y };
}
function tangentAngles(P, C, r) {
  var dx = C.x - P.x, dy = C.y - P.y, d = Math.hypot(dx, dy);
  if (d <= r * 1.02) return null;
  var base = Math.atan2(dy, dx), a = Math.asin(r / d);
  return [base - a, base + a];
}
function visAngle(P, C, r) {
  return 2 * Math.asin(Math.min(0.999, r / dist(P, C))) * 180 / Math.PI;
}

/* ---------- drawing helpers ---------- */
function mkLabel(grp, str, size, italic, weight) {
  var t = grp.text(str);
  t.font({
    family: SERIF, size: size, anchor: 'middle', leading: 1,
    style: italic ? 'italic' : 'normal', weight: weight || 'normal'
  });
  t.fill('#000');
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 8, 'stroke-linejoin': 'round' });
  return t;
}
function hoverable(el, text, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(text, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, body); });
  return el;
}

/* two tangent rays through the pinhole, running well past the far wall as in the plate */
function drawTangentRays(rayG, wedgeG, P, C, r, label) {
  var ang = tangentAngles(P, C, r);
  if (!ang) return;
  var ends = [];
  for (var i = 0; i < 2; i++) {
    var d = { x: Math.cos(ang[i]), y: Math.sin(ang[i]) };
    var ex = exitBox(P, d);
    ends.push(ex);
    var ln = rayG.line(P.x, P.y, ex.x, ex.y)
      .stroke({ color: RED, width: 6.2, linecap: 'butt' });
    hoverable(ln, label, 'Sight line',
      'A pinhole only passes rays that go through one point, so the image records the direction of each ray — the visual angle — and nothing at all about how far along that ray the object really sits.');
  }
  if (st.wedge) {
    wedgeG.polygon([[P.x, P.y], [ends[0].x, ends[0].y], [ends[1].x, ends[1].y]])
      .fill({ color: RED, opacity: 0.07 }).stroke('none');
  }
}

/* ---------- main render ---------- */
function amesRender() {
  amesRoot.clear();
  var g = geo();
  var showA = st.overlay !== 'Perceived';
  var showP = st.overlay !== 'Actual';

  var gWedge = amesRoot.group(), gRoom = amesRoot.group(), gThin = amesRoot.group(),
      gObj = amesRoot.group(), gRay = amesRoot.group(), gLab = amesRoot.group(),
      gUI = amesRoot.group();

  var pc = backProj(g.cL, g);
  var pr = Math.max(4, OBJR * pc.k);
  var pcorner = backProj({ x: WL, y: WT }, g);
  var xPL = Math.max(WL + 8, Math.min(WR - 80, pcorner.x));

  /* ---- actual room outline ---- */
  if (showA) {
    gRoom.polygon(g.poly.map(function (p) { return [p.x, p.y]; }))
      .fill('none').stroke({ color: '#000', width: 5, linejoin: 'miter' });
    var wall = gRoom.line(WL, WT, WR, g.yR).stroke({ color: '#000', width: 20, opacity: 0.001 });
    hoverable(wall, 'Actual far wall — slant ' + st.skew + '°', 'Actual far wall',
      'The real far wall recedes steeply on the left. Because a pinhole cannot measure depth, this slanted wall can project to exactly the same image as a wall square to the viewer.');
  }

  /* ---- perceived (assumed rectangular) plan ---- */
  if (showP) {
    gRoom.line(xPL, g.yR, WR, g.yR)
      .stroke({ color: '#000', width: 4.5, dasharray: '24,17', linecap: 'butt' });
    gRoom.line(xPL, g.yR, xPL, WB)
      .stroke({ color: '#000', width: 4.5, dasharray: '24,17', linecap: 'butt' });
    var hitH = gRoom.line(xPL, g.yR, WR, g.yR).stroke({ color: '#000', width: 20, opacity: 0.001 });
    hoverable(hitH, 'Perceived (assumed rectangular) floor plan', 'Perceived room',
      'This dashed rectangle is the room the brain assumes: right angles everywhere. It projects to the same image as the real trapezoid, so nothing in that image can rule it out.');
    var hitV = gRoom.line(xPL, g.yR, xPL, WB).stroke({ color: '#000', width: 20, opacity: 0.001 });
    hoverable(hitV, 'Perceived side wall — the back-projected far corner', 'Perceived side wall',
      'The ray that grazes the true far-left corner meets the assumed far wall here, so the brain places the room\'s left edge at this dashed line — and places anything on that ray right beside it.');
  }

  /* ---- thin black centre ray (under the objects, as in the plate) ---- */
  if (st.rays !== 'none') {
    var dC = { x: g.cL.x - g.P.x, y: g.cL.y - g.P.y };
    var n = Math.hypot(dC.x, dC.y); dC.x /= n; dC.y /= n;
    var exC = exitPt(g.P, dC, g.poly);
    gThin.line(g.P.x, g.P.y, exC.x, exC.y).stroke({ color: '#000', width: 1.8 });
  }

  /* ---- objects ---- */
  if (showA) {
    var c1 = gObj.circle(OBJR * 2).center(g.cL.x, g.cL.y)
      .fill(GRAY).stroke({ color: '#000', width: 5 });
    hoverable(c1, 'Far object — ' + visAngle(g.P, g.cL, OBJR).toFixed(1) + '° wide at the pinhole',
      'Far object (actual)',
      'This object sits in the deep far-left corner of the trapezoid. It is the same physical size as the other one, but it is much farther from the pinhole, so it fills only a narrow cone of directions.');
    var c2 = gObj.circle(OBJR * 2).center(g.cR.x, g.cR.y)
      .fill(GRAY).stroke({ color: '#000', width: 5 });
    hoverable(c2, 'Near object — ' + visAngle(g.P, g.cR, OBJR).toFixed(1) + '° wide at the pinhole',
      'Near object (actual)',
      'Physically identical to the far object, but much closer to the pinhole, so it fills a much wider angle. If the brain believes both are at the same depth, that angle difference is read as a size difference.');
  }
  if (showP && st.rays === 'back') {
    var c3 = gObj.circle(pr * 2).center(pc.x, pc.y)
      .fill(GRAY).stroke({ color: '#000', width: 4, dasharray: '12,9' });
    hoverable(c3, 'Perceived object — ' + (pc.k * 100).toFixed(0) + '% of the true size',
      'Perceived object',
      'Back-projecting the same sight lines onto the assumed rectangular floor lands the object right at the dashed side wall — much nearer than it really is. The same visual angle at a nearer assumed depth can only mean a smaller object.');
  }

  /* ---- red sight lines (over the objects, as in the plate) ---- */
  if (st.rays !== 'none') {
    drawTangentRays(gRay, gWedge, g.P, g.cL, OBJR, 'Sight line grazing the far object');
    if (st.rays === 'both') {
      drawTangentRays(gRay, gWedge, g.P, g.cR, OBJR, 'Sight line grazing the near object');
    }
  }

  /* ---- labels (drawn last, with white halos) ---- */
  if (showP && st.rays === 'back') {
    var edge = Math.min(xPL, pc.x - pr) - 28;
    var l1 = mkLabel(gLab, 'Perceived', 31, false);
    var l2 = mkLabel(gLab, 'object', 31, false);
    var b1 = l1.bbox(), b2 = l2.bbox();
    if (edge - b1.width > WL - 6) {
      l1.center(edge - b1.width / 2, pc.y - 19);
      l2.center(edge - b2.width / 2, pc.y + 20);
    } else {
      var rx = Math.max(pc.x + pr, xPL) + 26;
      l1.center(Math.min(rx + b1.width / 2, WR - b1.width / 2 - 8), pc.y - 19);
      l2.center(Math.min(rx + b2.width / 2, WR - b2.width / 2 - 8), pc.y + 20);
    }
  }
  if (showA) {
    var mx = WL + 0.47 * (WR - WL), my = g.wy(mx);
    var tA = mkLabel(gLab, 'Actual room floor plan', 36, true, '500');
    tA.center(mx + 25 * g.m / g.nn, my - 25 / g.nn);
    tA.rotate(Math.atan2(g.m, 1) * 180 / Math.PI);
  }
  if (showP) {
    var belowLine = (showA && st.skew < 7);
    var tP = mkLabel(gLab, 'Perceived room floor plan', 34, false, '500');
    var bw = tP.bbox().width;
    var cxMax = WR - bw / 2 - 10;
    var cx = Math.min(cxMax, Math.max(xPL + bw / 2 + 4, 0.60 * VBW));
    tP.center(cx, g.yR + (belowLine ? 30 : -22));
  }

  /* ---- pinhole ---- */
  var ph = gUI.circle(16).center(g.P.x, g.P.y).fill('#000');
  var hit = gUI.circle(52).center(g.P.x, g.P.y).fill('#ffffff').attr('fill-opacity', 0.001);
  mkLabel(gLab, 'Pinhole', 30, false).center(Math.min(WR - 52, Math.max(WL + 52, g.P.x)), WB + 32);

  if (st.hint) {
    var ring = gUI.circle(46).center(g.P.x, g.P.y).fill('none').stroke({ color: RED, width: 3 });
    try { ring.animate(900).attr({ 'stroke-opacity': 0.05 }).loop(true, true); } catch (e) { }
  }
  hoverable(hit, 'Drag me along the bottom wall', 'Pinhole',
    'All the light reaching the eye passes through this single point, so only ray directions survive. Move it and the whole construction changes: an Ames room is built for exactly one viewpoint.');
  hit.css('cursor', 'ew-resize');
  ph.css('cursor', 'ew-resize');
  hit.on('pointerdown', function (e) { amesDragging = true; e.preventDefault(); });
  ph.on('pointerdown', function (e) { amesDragging = true; e.preventDefault(); });
}

/* ---------- drag ---------- */
var amesDragging = false;
document.addEventListener('pointermove', function (e) {
  if (!amesDragging) return;
  var p = amesDraw.point(e.clientX, e.clientY);
  var x = Math.max(160, Math.min(610, p.x));
  st.px = x;
  var inp = document.getElementById('pinholeDragInput'); if (inp) inp.value = Math.round(x);
  var out = document.getElementById('pinholeDragVal'); if (out) out.value = Math.round(x);
  amesRender(); updReadout();
});
document.addEventListener('pointerup', function () { amesDragging = false; });

/* ---------- readout ---------- */
function updReadout() {
  var el = document.getElementById('amesReadout');
  if (!el) return;
  var g = geo();
  var aL = visAngle(g.P, g.cL, OBJR), aR = visAngle(g.P, g.cR, OBJR);
  var kL = backProj(g.cL, g).k, kR = backProj(g.cR, g).k;
  var ratio = kR / kL;
  el.innerHTML =
    'The two gray objects are <b>the same real size</b>.<br>' +
    'Visual angle at the pinhole — far <b>' + aL.toFixed(1) + '°</b>, near <b>' + aR.toFixed(1) + '°</b><br>' +
    'Assumed depth ÷ true depth — far <b>' + kL.toFixed(2) + '</b>, near <b>' + kR.toFixed(2) + '</b><br>' +
    'Perceived size — far <b>' + (kL * 100).toFixed(0) + '%</b> of true, near <b>' + (kR * 100).toFixed(0) + '%</b><br>' +
    (Math.abs(ratio - 1) < 0.01
      ? '<b>No illusion:</b> both look their true size.'
      : 'So the near object <b>looks ' + ratio.toFixed(2) + '×</b> bigger than the far one.');
}

/* ---------- interaction handlers ---------- */
function update_skewAngle(v) { st.skew = v; amesRender(); updReadout(); }
function update_pinholeDrag(v) { st.px = v; amesRender(); updReadout(); }
function toggle_planOverlay(v) { st.overlay = v; amesRender(); updReadout(); }
function toggle_rayReveal(v) { st.rays = v; amesRender(); updReadout(); }
function toggle_wedgeShade(on) { st.wedge = !!on; amesRender(); }

/* ---------- demo steps ---------- */
var STEPS = [
  {
    title: 'The published figure',
    narration: 'Top-down plan of an Ames room. Solid black = the true trapezoidal floor, dashed black = the rectangular room the viewer assumes, red = sight lines through the pinhole. Press ▶ to build it up step by step.',
    state: { planOverlay: 'Both', rayReveal: 'back', skewAngle: 25, px: 424, wedge: false, hint: false }
  },
  {
    title: 'The actual room',
    narration: 'Seen from above, the real room is a trapezoid: the far wall recedes sharply away on the left. Two identical gray objects sit in the far-left and near-right corners.',
    state: { planOverlay: 'Actual', rayReveal: 'none', skewAngle: 25, px: 424, wedge: false, hint: false }
  },
  {
    title: 'Rays through the pinhole',
    narration: 'Red tangent rays graze each object and run on past the far wall. The objects are identical, yet the near-right one fills a much wider angle than the far-left one — because the pinhole records only directions, never distances.',
    state: { planOverlay: 'Actual', rayReveal: 'both', skewAngle: 25, px: 424, wedge: true, hint: false }
  },
  {
    title: 'The room the brain assumes',
    narration: 'The viewer assumes an ordinary rectangular room. The dashed rectangle is that assumed floor plan — it is consistent with the very same image, so nothing in the picture contradicts it.',
    state: { planOverlay: 'Both', rayReveal: 'both', skewAngle: 25, px: 424, wedge: false, hint: false }
  },
  {
    title: "Where the object is 'placed'",
    narration: 'Back-projecting the far object\'s rays onto the assumed floor lands it at the dashed circle, right on the perceived side wall — much nearer than it really is. Same visual angle at a nearer assumed depth means a smaller object.',
    state: { planOverlay: 'Both', rayReveal: 'back', skewAngle: 25, px: 424, wedge: false, hint: false }
  },
  {
    title: 'Crank up the skew',
    narration: 'Increase the far-wall slant: the true depth difference grows while the assumed depth stays put, so the perceived size of the far object collapses and two identical objects look dramatically different.',
    state: { planOverlay: 'Both', rayReveal: 'back', skewAngle: 40, px: 424, wedge: false, hint: false }
  },
  {
    title: 'Flatten the room',
    narration: 'Set the skew to zero and the room really is rectangular — perceived and actual floor plans coincide, perceived size equals true size, and the illusion vanishes entirely.',
    state: { planOverlay: 'Both', rayReveal: 'back', skewAngle: 0, px: 424, wedge: false, hint: false }
  },
  {
    title: 'One viewpoint only',
    narration: 'Now drag the pinhole along the bottom wall. The rays swing, the perceived object slides to a new place, and the trapezoid stops masquerading as a rectangle — the illusion works from exactly one point of view.',
    state: { planOverlay: 'Both', rayReveal: 'back', skewAngle: 25, px: 424, wedge: false, hint: true }
  }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = Math.max(0, Math.min(STEPS.length - 1, i));
  var s = STEPS[stepIdx], v = s.state;

  st.skew = v.skewAngle; st.px = v.px; st.overlay = v.planOverlay;
  st.rays = v.rayReveal; st.wedge = !!v.wedge; st.hint = !!v.hint;

  var e;
  e = document.getElementById('skewAngleInput'); if (e) e.value = v.skewAngle;
  e = document.getElementById('skewAngleVal'); if (e) e.value = v.skewAngle;
  e = document.getElementById('pinholeDragInput'); if (e) e.value = v.px;
  e = document.getElementById('pinholeDragVal'); if (e) e.value = v.px;
  e = document.getElementById('planOverlayInput'); if (e) e.value = v.planOverlay;
  e = document.getElementById('rayRevealInput'); if (e) e.value = v.rayReveal;
  e = document.getElementById('wedgeShadeInput'); if (e) e.checked = !!v.wedge;

  var n = document.getElementById('demoNarration');
  if (n) n.innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = (stepIdx === 0) ? 'start' : stepIdx + ' / ' + (STEPS.length - 1);

  amesRender(); updReadout();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ---------- init ---------- */
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

